import {chromium} from '@playwright/test';
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {scenarioState,makeTask,KEY} from '../src/model.js';
const dir='检查记录/执行复盘重设计_20261021',browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']});
const p=await browser.newPage(),results=[],errors=[];p.setDefaultTimeout(10000);p.setDefaultNavigationTimeout(30000);p.on('pageerror',e=>errors.push(e.message));
async function load(s,width,route,lang='zh'){await p.setViewportSize({width,height:width===390?844:1000});await p.goto('http://127.0.0.1:5184/plan',{waitUntil:'domcontentloaded'});await p.evaluate(({s,k,lang})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{s,k:KEY,lang});await p.goto('http://127.0.0.1:5184'+route,{waitUntil:'domcontentloaded'});await p.locator('.action-cycle').waitFor();await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});}
async function shot(name){await p.locator('.action-cycle').evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/'+name+'-视口.png'});const v=p.viewportSize(),box=await p.locator('.action-cycle').boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(box.height+650)});const style=await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'});await p.locator('.action-cycle').screenshot({path:dir+'/'+name+'-板块.png'});await style.evaluate(e=>e.remove());await p.setViewportSize(v);}
try{
for(const width of [1440,390]){const s=scenarioState('PT05');s.tasks.push({...makeTask(s,{title:'受阻行动（合成）',hours:1,purpose:'澄清输入',product:'输入说明'}),id:'blocked',status:'受阻',note:'尚缺原始数据'});if(width===390)for(let i=0;i<14;i++)s.tasks.unshift({...makeTask(s,{title:'前列行动（合成）'+i,hours:0,purpose:'合成'}),id:'filler-'+i});await load(s,width,'/plan?tab=执行&task=blocked');const prior=await p.evaluate(k=>localStorage.getItem(k),KEY);await p.locator('.flow-next').click();assert.equal(await p.locator('.action-focus-paper').evaluate(e=>document.activeElement===e),true);assert.equal(await p.evaluate(k=>localStorage.getItem(k),KEY),prior);const c=p.getByRole('button',{name:'记录并处理阻塞',exact:true}),b=await c.boundingBox(),f=await p.locator('.flow-progress').boundingBox();assert.ok(b.y>=0&&b.y+b.height<f.y,JSON.stringify({b,f}));await p.screenshot({path:dir+'/'+width+'-所选行动主操作-视口.png'});if(width===1440)await shot('1440-执行队列');await c.click();assert.equal(await p.locator('dialog[open]').count(),1);assert.equal(new URL(p.url()).pathname,'/plan');results.push({name:width+'底栏承接所选行动、操作可见且不直接开始',status:'pass'});}
await load(scenarioState('PT01'),390,'/plan?tab=执行','en');for(const attr of ['placeholder','aria-label'])assert.doesNotMatch(await p.locator('.action-cycle textarea').getAttribute(attr),/[\u4e00-\u9fff]/);await shot('390-执行英文');results.push({name:'执行textarea英文提示与可访问名称',status:'pass'});
await load(scenarioState('PT05'),390,'/plan?tab=复盘','en');for(const step of [0,1,2]){await p.locator('.review-step-tabs button').nth(step).click();for(const ta of await p.locator('.review-step-content textarea').all())for(const attr of ['placeholder','aria-label'])assert.doesNotMatch(await ta.getAttribute(attr),/[\u4e00-\u9fff]/);}await p.locator('.review-step-tabs button').first().click();await p.locator('textarea[name=result]').fill('USER_INPUT 原文保留');assert.equal(await p.locator('textarea[name=result]').inputValue(),'USER_INPUT 原文保留');await shot('390-复盘英文写作');results.push({name:'复盘各步textarea英文提示，用户输入原文保留',status:'pass'});
assert.deepEqual(errors,[]);
}finally{await fs.writeFile(dir+'/独立复核修正验证.json',JSON.stringify({results,errors},null,2));await browser.close();}
console.log(JSON.stringify({results,errors},null,2));
